var i=`0353-apfelstrudel`;var t=`world-0353`;var a=`DE`;var r=`western-europe`;var o=8;var s=77;var l={en:`Apfelstrudel`,ua:`Яблучний штрудель`};var d={en:`A traditional Germany dish made with apple, raisin, lemon juice, breadcrumbs. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: яблуко, родзинки, лимонний сік, панірувальні сухарі. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:13,i:[[`apple`,850,`g`],[`raisin`,120,`g`],[`white-granulated-sugar`,120,`g`],[`ground-cinnamon`,7,`g`],[`lemon-juice`,30,`ml`],[`breadcrumbs`,75,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[[`phyllo-pastry`,300,`g`],[`unsalted-butter`,120,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:10,i:[]},{en:`Bake in a preheated 180°C oven for about 37 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 37 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:37,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,45,`g`]]}];var u={slug:i,id:t,country:`DE`,region:r,servings:8,minutes:77,title:l,text:d,steps:g};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,i as slug,g as steps,d as text,l as title};